package io.github.pradyumnadp.blobface

/** Reads a fixture file from disk (see FIXTURE_DIR, generated by the build). */
internal expect fun readFixtureFile(path: String): String

internal fun fixture(name: String): String = readFixtureFile("$FIXTURE_DIR/fixtures/$name")

/**
 * Correctly-rounded decimal → double. Kotlin/Wasm's `String.toDouble()` is off by
 * one ulp for some shortest-form decimals (e.g. "49.41959497588687"), so the Wasm
 * actual delegates to JavaScript's `parseFloat`; every other platform's parser is
 * exact.
 */
internal expect fun parseFixtureDouble(s: String): Double
